from .money import _to_cents, _from_cents, MAX_CENTS, format_amount


def make_invoice(amounts):
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    items = list(amounts)
    total = 0
    for item in items:
        total += _to_cents(item)
        if total > MAX_CENTS:
            raise ValueError("total too large")
    return {"total": format_amount(_from_cents(total)), "count": len(items)}
